1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type ClaimStep = {
19	  op: "claim";
20	  policy: number;
21	  incident: { cause: string; damages: Damage[] };
22	};
23	
24	export type Step = QuoteStep | ClaimStep;
25	
26	export type Customer = {
27	  yearsWithMHPCO: number;
28	};
29	
30	export type Scenario = {
31	  customer: Customer;
32	  steps: Step[];
33	};
34	
35	export type ScenarioResults = {
36	  results: unknown[];
37	};
38	
39	const PROCESSING_FEE = 5;
40	const FIRST_INSURANCE_SURCHARGE = 0.1;
41	const CURSE_SURCHARGE = 0.5;
42	const HIGH_ENCHANTMENT_THRESHOLD = 5;
43	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
44	const LOYALTY_YEARS_THRESHOLD = 2;
45	const LOYALTY_DISCOUNT = 0.2;
46	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
47	const DEDUCTIBLE = 100;
48	const CAP_MULTIPLIER = 2;
49	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
50	const HIGH_ENCHANTMENT_REIMBURSEMENT = 0.5;
51	
52	const INSURANCE_VALUES: Record<string, number> = {
53	  sword: 1000,
54	  amulet: 600,
55	  staff: 800,
56	  potion: 400,
57	  rune: 250,
58	  moonstone: 250,
59	};
60	
61	const ITEM_BASE_PREMIUMS: Record<string, number> = {
62	  sword: 100,
63	  amulet: 60,
64	  staff: 80,
65	  potion: 40,
66	  rune: 25,
67	  moonstone: 25,
68	};
69	
70	/** Premiums round up: the MHPCO's favour is the higher number. */
71	const roundPremiumInMHPCOsFavour = (premium: number): number =>
72	  Math.ceil(premium);
73	
74	const BLOCK_SIZE = 3;
75	const BLOCK_BASE_PREMIUM = 60;
76	
77	const countByType = (items: Item[]): Map<string, number> => {
78	  const counts = new Map<string, number>();
79	  for (const item of items) {
80	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
81	  }
82	  return counts;
83	};
84	
85	const basePremiumForGroup = (type: string, count: number): number =>
86	  count === BLOCK_SIZE
87	    ? BLOCK_BASE_PREMIUM
88	    : count * ITEM_BASE_PREMIUMS[type];
89	
90	const policyBasePremium = (items: Item[]): number =>
91	  [...countByType(items)].reduce(
92	    (total, [type, count]) => total + basePremiumForGroup(type, count),
93	    0,
94	  );
95	
96	type SurchargeRule = {
97	  appliesTo: (item: Item) => boolean;
98	  rate: number;
99	};
100	
101	const SURCHARGE_RULES: SurchargeRule[] = [
102	  {
103	    appliesTo: (item) => item.cursed === true,
104	    rate: CURSE_SURCHARGE,
105	  },
106	  {
107	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
108	    rate: HIGH_ENCHANTMENT_SURCHARGE,
109	  },
110	];
111	
112	const itemSurcharge = (item: Item): number => {
113	  const itemBasePremium = ITEM_BASE_PREMIUMS[item.type];
114	  return SURCHARGE_RULES.filter((rule) => rule.appliesTo(item)).reduce(
115	    (surcharge, rule) => surcharge + itemBasePremium * rule.rate,
116	    0,
117	  );
118	};
119	
120	const sumItemSurcharges = (items: Item[]): number =>
121	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
122	
123	type PolicyContext = {
124	  customer: Customer;
125	  isFollowUpContract: boolean;
126	};
127	
128	type PolicyModifierRule = {
129	  appliesTo: (context: PolicyContext) => boolean;
130	  /** Signed rate applied to the policy base premium: positive adds, negative discounts. */
131	  rate: number;
132	};
133	
134	const POLICY_MODIFIER_RULES: PolicyModifierRule[] = [
135	  {
136	    appliesTo: () => true,
137	    rate: FIRST_INSURANCE_SURCHARGE,
138	  },
139	  {
140	    appliesTo: ({ customer }) =>
141	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
142	    rate: -LOYALTY_DISCOUNT,
143	  },
144	  {
145	    appliesTo: ({ isFollowUpContract }) => isFollowUpContract,
146	    rate: -FOLLOW_UP_CONTRACT_DISCOUNT,
147	  },
148	];
149	
150	const sumPolicyModifiers = (
151	  basePremium: number,
152	  context: PolicyContext,
153	): number =>
154	  POLICY_MODIFIER_RULES.filter((rule) => rule.appliesTo(context)).reduce(
155	    (total, rule) => total + basePremium * rule.rate,
156	    0,
157	  );
158	
159	const quotePremium = (items: Item[], context: PolicyContext): number => {
160	  const basePremium = policyBasePremium(items);
161	  return roundPremiumInMHPCOsFavour(
162	    basePremium +
163	      sumItemSurcharges(items) +
164	      sumPolicyModifiers(basePremium, context) +
165	      PROCESSING_FEE,
166	  );
167	};
168	
169	const insuranceSum = (items: Item[]): number =>
170	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
171	
172	const reimbursementFor = (damage: Damage, insuredItems: Item[]): number => {
173	  const item = insuredItems.find((candidate) => candidate.type === damage.itemType);
174	  const isHighlyEnchanted =
175	    (item?.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD;
176	  return isHighlyEnchanted
177	    ? damage.amount * HIGH_ENCHANTMENT_REIMBURSEMENT
178	    : damage.amount;
179	};
180	
181	const claimPayout = (damages: Damage[], insuredItems: Item[]): number =>
182	  damages.reduce(
183	    (sum, damage) => sum + reimbursementFor(damage, insuredItems) - DEDUCTIBLE,
184	    0,
185	  );
186	
187	/**
188	 * Tracks how much cover each policy has left. A policy is identified by the
189	 * step index of the quote that created it, which is how claims refer to it.
190	 */
191	type PolicyLedger = {
192	  open: (policyId: number, items: Item[]) => void;
193	  insuredItems: (policyId: number) => Item[];
194	  /** Pays out at most the policy's remaining cap. */
195	  drawDown: (policyId: number, desiredPayout: number) => ClaimResult;
196	};
197	
198	const createPolicyLedger = (): PolicyLedger => {
199	  const remainingCaps = new Map<number, number>();
200	  const insuredItems = new Map<number, Item[]>();
201	
202	  return {
203	    open: (policyId, items) => {
204	      remainingCaps.set(policyId, insuranceSum(items) * CAP_MULTIPLIER);
205	      insuredItems.set(policyId, items);
206	    },
207	
208	    insuredItems: (policyId) => insuredItems.get(policyId) ?? [],
209	
210	    drawDown: (policyId, desiredPayout) => {
211	      const cap = remainingCaps.get(policyId) ?? 0;
212	      const payout = Math.min(desiredPayout, cap);
213	      const remainingCap = cap - payout;
214	      remainingCaps.set(policyId, remainingCap);
215	      return { payout, remainingCap };
216	    },
217	  };
218	};
219	
220	type QuoteResult = { premium: number };
221	type ClaimResult = { payout: number; remainingCap: number };
222	
223	const processQuote = (
224	  step: QuoteStep,
225	  policyId: number,
226	  scenario: Scenario,
227	  ledger: PolicyLedger,
228	): QuoteResult => {
229	  ledger.open(policyId, step.items);
230	  return {
231	    premium: quotePremium(step.items, {
232	      customer: scenario.customer,
233	      isFollowUpContract: policyId > 0,
234	    }),
235	  };
236	};
237	
238	const processClaim = (step: ClaimStep, ledger: PolicyLedger): ClaimResult =>
239	  ledger.drawDown(
240	    step.policy,
241	    claimPayout(step.incident.damages, ledger.insuredItems(step.policy)),
242	  );
243	
244	export const runScenario = (scenario: Scenario): ScenarioResults => {
245	  const ledger = createPolicyLedger();
246	
247	  const results = scenario.steps.map((step, index) =>
248	    step.op === "quote"
249	      ? processQuote(step, index, scenario, ledger)
250	      : processClaim(step, ledger),
251	  );
252	
253	  return { results };
254	};
